import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.Boholvbs.js";const c=JSON.parse('{"title":"JEO Plugin","description":"","frontmatter":{},"headers":[],"relativePath":"index-plugin.md","filePath":"index-plugin.md"}'),o={name:"index-plugin.md"};function l(n,e,s,d,h,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="jeo-plugin" tabindex="-1">JEO Plugin <a class="header-anchor" href="#jeo-plugin" aria-label="Permalink to &quot;JEO Plugin&quot;">​</a></h1><p>The JEO plugin acts as a geojournalism platform that allows news organizations, bloggers and NGOs to publish news stories as layers of information on digital maps. With JEO, creating the interaction between data layers and contextual information is intuitive and interactive.</p><p>You can post geolocated stories and create richly designed pages for each one of the featured stories. At the same time, by configuring layers hosted on Mapbox and choosing between MapboxGL and MapLibreGL, you can manage sophisticated maps without losing performance, add legends directly with HTML and set the map parameters. All directly at the WordPress dashboard.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><a href="https://www.mapbox.com/" target="_blank" rel="noreferrer">Mapbox</a> and <a href="https://maplibre.org/" target="_blank" rel="noreferrer">MapLibre</a> maps</li><li><a href="https://visgl.github.io/react-map-gl/" target="_blank" rel="noreferrer">react-map-gl</a> library</li><li>Custom tile layers</li><li>Layer filtering options, allowing you to mix tile layer.</li><li>Geocoding WordPress posts using OpenStreetMap (Nominatim), supporting the post type <code>Post</code>, with extensibility for additional geocoders via hook.</li><li>Customizable marker icons that can be associated to categories, custom taxonomies or posts directly.</li><li>Map markers query integrated to posts query.</li><li>Support <a href="https://wpml.org/pt-br/" target="_blank" rel="noreferrer">WPML</a> and <a href="https://wordpress.org/plugins/polylang/" target="_blank" rel="noreferrer">Polylang</a> multilingual plugins</li><li>AI-powered georeferencing, bulk geolocation, and map generation (multiple AI providers)</li><li>Stories Near You block with geolocation-based post discovery</li><li>AI-assisted map block (Minimap) with chat refinement and auto-generated layers</li></ul><h2 id="user-tutorials" tabindex="-1">User tutorials <a class="header-anchor" href="#user-tutorials" aria-label="Permalink to &quot;User tutorials&quot;">​</a></h2><h3 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h3><ul><li><a href="./concepts">Concepts</a></li><li><a href="./getting-started">Installing and configuring the plugin</a></li></ul><h3 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h3><ul><li><a href="./layer-post">Creating layers</a></li></ul><h3 id="maps" tabindex="-1">Maps <a class="header-anchor" href="#maps" aria-label="Permalink to &quot;Maps&quot;">​</a></h3><ul><li><a href="./map-post">Creating maps</a></li></ul><h3 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h3><ul><li><a href="./discovery">Using discovery</a></li></ul><h3 id="story-map" tabindex="-1">Story Map <a class="header-anchor" href="#story-map" aria-label="Permalink to &quot;Story Map&quot;">​</a></h3><ul><li><a href="./story-map">Creating and using Story Map</a></li></ul><h3 id="posts" tabindex="-1">Posts <a class="header-anchor" href="#posts" aria-label="Permalink to &quot;Posts&quot;">​</a></h3><ul><li><a href="./geolocating-posts">Geolocating posts</a></li><li><a href="./ai-georeferencing">AI Georeferencing</a></li><li><a href="./ai-bulk-geolocation">AI Bulk Geolocation</a></li><li><a href="./map-shortcode">Using a map shortcode</a></li><li><a href="./map-block">Using a map block</a></li><li><a href="./one-time-map-block">Using an one-time map block</a></li><li><a href="./map-embed">Using a map embed</a></li></ul><h3 id="ai-features" tabindex="-1">AI Features <a class="header-anchor" href="#ai-features" aria-label="Permalink to &quot;AI Features&quot;">​</a></h3><ul><li><a href="./ai-settings">AI Settings</a></li><li><a href="./minimap">Minimap — AI-Assisted Map Block</a></li></ul><h3 id="stories-near-you" tabindex="-1">Stories Near You <a class="header-anchor" href="#stories-near-you" aria-label="Permalink to &quot;Stories Near You&quot;">​</a></h3><ul><li><a href="./stories-near-you">Stories Near You block</a></li></ul><h2 id="developer-documentation" tabindex="-1">Developer documentation <a class="header-anchor" href="#developer-documentation" aria-label="Permalink to &quot;Developer documentation&quot;">​</a></h2><h3 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials&quot;">​</a></h3><ul><li><a href="./dev/layer-types">Adding new Layer Types</a></li><li><a href="./dev/geo-information">Geographical Information of a post</a></li><li><a href="./dev/geocoders">Writing a Geocoder</a></li></ul><h3 id="differences-between-the-old-and-the-present-jeo" tabindex="-1">Differences between the old and the present JEO <a class="header-anchor" href="#differences-between-the-old-and-the-present-jeo" aria-label="Permalink to &quot;Differences between the old and the present JEO&quot;">​</a></h3><ul><li><a href="./dev/migration">Migration</a></li></ul>',27)])])}const g=a(o,[["render",l]]);export{c as __pageData,g as default};
